export const getExportSpecUrl = (projectId: string,
    specId: string,
    params?: ExportSpecParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${projectId}/specs/${specId}/export?${stringifiedParams}` : `/api/projects/${projectId}/specs/${specId}/export`
}

export const exportSpec = async (projectId: string,
    specId: string,
    params?: ExportSpecParams, options?: Parameters<typeof apiFetch>[1]): Promise<ExportSpec200> => {

  return apiFetch<ExportSpec200>(getExportSpecUrl(projectId,specId,params),
  {
    ...options,
    method: 'GET'


  }
);}





